import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address jojoAddr, string calldata desc) public {
        vm.assume(jojoAddr != address(0));
        // Set up the JOJO team
        vm.prank(address(this));
        // c.jojoTeam is not initialised, we need a way to set it.
        // Since there is no setter, we use vm.store to set the jojoTeam slot.
        // Slot computation: jojoTeam is declared after event NewEmergencyOracle (no slot) and address public jojoTeam.
        // The layout: event doesn't occupy storage. address jojoTeam is the second state variable after nothing else? 
        // Contract C has: event NewEmergencyOracle (doesn't use storage), address public jojoTeam (slot 0).
        // We use vm.prank and call the function via onlyJojoTeam modifier. So we need to set c.jojoTeam.
        bytes32 slot = bytes32(uint256(0));
        vm.store(address(c), slot, bytes32(uint256(uint160(jojoAddr))));
        // Now jojoAddr is the jojoTeam.
        vm.prank(jojoAddr);
        c.newEmergencyOracle(desc);
        // Retrieve the oracle address from the emitted event? No, we can read the event log.
        // Instead, we can parse the logs. The event NewEmergencyOracle emits (owner, newOracle).
        // We need the newOracle address to check its owner.
        vm.recordLogs();
        vm.prank(jojoAddr);
        c.newEmergencyOracle(desc);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // logs[0] should be the event NewEmergencyOracle
        // The event has indexed parameters? No, event NewEmergencyOracle(address owner, address newOracle); no indexed.
        // The data is abi.encode(owner, newOracle)
        require(logs.length > 0, "no logs");
        (address loggedOwner, address newOracle) = abi.decode(logs[0].data, (address, address));
        // The newEmergencyOracle function is called by jojoAddr, so jojoAddr is msg.sender.
        // Check that the owner of the deployed EmergencyOracle contract is jojoAddr.
        // EmergencyOracle has owner() view returns address.
        (bool ok, bytes memory data) = newOracle.staticcall(abi.encodeWithSignature("owner()"));
        require(ok, "owner call failed");
        address oracleOwner = abi.decode(data, (address));
        assertTrue(oracleOwner == jojoAddr);
    }
}

