    function testFuzz_property(string calldata description) public {
        // Compute the address of the EmergencyOracle that will be deployed with nonce 1.
        // Reference: https://ethereum.stackexchange.com/questions/760/how-is-the-address-of-an-ethereum-contract-computed
        address predictedOracle = address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xd6),
            bytes1(0x94),
            address(c),
            bytes1(0x01)
        )))));

        // Ensure that the predicted address does not already have code (shouldn't).
        // But if the fuzzer somehow ran multiple times? Not possible.

        // The only legitimate caller is jojoTeam, which is address(0).
        vm.prank(address(0));
        c.newEmergencyOracle(description);

        // Now the oracle is deployed at predictedOracle. Check its owner.
        IEmergencyOracle oracle = IEmergencyOracle(predictedOracle);
        address actualOwner = oracle.owner();

        // The rule: The owner of the newly created EmergencyOracle must be the caller of newEmergencyOracle (address(0)).
        // In the reference, this holds. In the bug, owner is 0x1, so this fails.
        assertTrue(actualOwner == address(0));
    }
}

